using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;

var normalizer = new FdcNormalizer();
var descs = new (string Desc, FdcDataset Ds, string ParsedName)[]
{
	("Tomatoes, crushed, canned", FdcDataset.Foundation, "crushed tomatoes"),
	("Tomato, roma", FdcDataset.Foundation, "crushed tomatoes"),
	("Bread, crumbs, dry, grated, plain", FdcDataset.Foundation, "bread"),
	("Bread, white, commercially prepared (includes soft bread crumbs)", FdcDataset.Foundation, "bread"),
	("Nuts, almonds, whole, raw", FdcDataset.Foundation, "blanched almonds"),
	("Nuts, almonds, blanched", FdcDataset.Foundation, "blanched almonds"),
};
foreach (var (d, ds, pn) in descs)
{
	var parsed = FdcDescriptionParser.Parse(d, ds);
	var tokens = normalizer.NormalizeToTokens(d);
	var state = FdcMatcher.ExtractCandidateState(tokens);
	var sat = FdcMatcher.ExtractCandidateSatisfiers(tokens);
	Console.WriteLine($"desc='{d}' ds={ds} head='{parsed.HeadTerm}' quals=[{string.Join(" ", parsed.Qualifiers)}] state={state} sat={sat} tokens=[{string.Join(" ", tokens)}]");
}
