{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row vs the key row <b>relation</b>
/// and the decision <b>site</b> — using the production helpers (F-428 P12.13, D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary><c>no-label</c>: the line has no labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary><c>pack-unit-state</c>: a can/jar unit line whose key is Canned and the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary><c>compound-head-lost</c>: the key head phrase is multi-word and the parsed name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary><c>state-mismatch</c>: the head terms agree but the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary><c>row-choice-tier</c>: head and state agree but the rows sit on different dataset tiers.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary><c>same-head-other-qualifier</c>: head, state and tier agree; only the qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary><c>sibling-food</c>: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary><c>other</c>: no relation rule held, or a field a rule needed was missing.</summary>
	public const string RelationOther = "other";

	/// <summary><c>reuse</c>: ranker path, row reused from an existing master.</summary>
	public const string SiteReuse = "reuse";

	/// <summary><c>override</c>: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary><c>curated</c>: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary><c>ranker</c>: ranker path, fresh row.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Reusable single-token list for the per-token state checks (single-threaded runner).</summary>
	private readonly List<string> _singleToken = [];

	private readonly FdcLexicon _lexicon = FdcLexicon.Default;

	/// <summary>Creates a classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The exact-override key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins (brief §4 order);
	/// a missing field a rule needs yields <see cref="RelationOther"/> with <see cref="ClassificationResult.MissingField"/>.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var parsedName = atom?.ParsedName ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedHeadParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyHeadParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedHeadParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		result.Site = ClassifySite(atom, line.RawText);
		if (result.Site == SiteOverride)
		{
			result.OverrideKey = _overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no";
		}

		result.Relation = ClassifyRelation(
			line.RawText,
			keyDesc,
			acceptedDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			keyHead,
			acceptedHead,
			parsedNameTokens,
			keyHeadPhrase,
			keyHeadParsed,
			acceptedHeadParsed,
			result);

		return result;
	}

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to (excluding) the first token the
	/// production state/modifier vocabulary marks as non-head — <see cref="FdcLexicon.ModifierWords"/>
	/// or a token <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// reports as state. "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>;
	/// "Tomatoes, crushed, canned" → <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key row's normalized tokens.</param>
	/// <returns>The head phrase tokens, each singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifier(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds
	/// <c>StateAgrees</c> (FdcMatcher.cs:1155-1157).
	/// </summary>
	/// <param name="tokens">A normalized token list.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The production reuse rule applied to the line's own name and the master it linked:
	/// <see cref="IngredientLineResolver.ShouldReuse"/> on the computed slug and the linked id.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug, or null.</param>
	/// <returns><see langword="true"/> when the production rule would reuse that master for this name.</returns>
	public bool ShouldReuseLinkedMaster(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		string rawText,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase,
		ParsedFdcDescription keyHeadParsed,
		ParsedFdcDescription acceptedHeadParsed,
		ClassificationResult result)
	{
		// 1. no-label: the line has no labelled row.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return RelationNoLabel;
		}

		// 2. pack-unit-state: a can/jar unit in the raw line; the key is Canned, the accepted row is not.
		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return RelationPackUnitState;
		}

		// 3. compound-head-lost: the key head phrase is multi-word and the parsed name kept only its first word.
		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return RelationCompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		if (headsAgree)
		{
			// 4. state-mismatch: the head terms agree, the state masks differ.
			if (keyState != acceptedState)
			{
				return RelationStateMismatch;
			}

			// 5. row-choice-tier: head and state agree, the dataset tiers differ.
			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return RelationOther;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				return RelationRowChoiceTier;
			}

			// 6. same-head-other-qualifier: head, state and tier agree; record the qualifier difference.
			var keyQualifiers = SingularPhraseList(keyHeadParsed.Qualifiers);
			var acceptedQualifiers = SingularPhraseList(acceptedHeadParsed.Qualifiers);
			result.KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			result.AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			return RelationSameHeadOtherQualifier;
		}

		// 7. sibling-food: the head terms differ.
		return RelationSiblingFood;
	}

	private bool IsStateOrModifier(string token)
	{
		if (_lexicon.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>
	/// Folds a raw line the way the matcher folds it for the raw-key override lookup
	/// (FdcMatcher.cs:165): lower-cased, trimmed, content from the first <c>(</c> dropped.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's lower-cased override lookup.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
