{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the accepted row vs the key row
/// (<see cref="ClassificationResult.Relation"/>) and the decision site
/// (<see cref="ClassificationResult.Site"/>). Every relation test calls production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> — never a copy of matcher logic (D-014).
/// Not thread-safe: one <c>Classify</c> call at a time.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Raw-text can/jar unit token — the pack-unit shape in P12.13 brief §2.</summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;

	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks; ExtractCandidateState/Satisfiers only
	// read the list, so re-filling one cell per token is safe on this single-threaded runner and
	// keeps the census allocation-free (CA1861 forbids the constant-array argument form anyway).
	private readonly string[] _singleToken = new string[1];

	/// <summary>Creates the classifier over the production normalizer and the shipped override keys.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Site: the ranker matched a row that was then reused against an existing master.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the ranker picked a fresh row (not reused).</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Site: an override file resolved the line.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue resolved the line.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Relation: the label is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: the label wants a canned row; the accepted row is not canned.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parser name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; qualifier tokens differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds (typically a missing trace field).</summary>
	public const string RelationOther = "other";

	/// <summary>Classifies one trace line. Only <c>auto &amp;&amp; !correct</c> lines are meant for this call.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and the recorded row facts.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = ChooseAtom(line);
		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var parsedNameTokens = SingularTokens(_normalizer.NormalizeToTokens(atom.ParsedName));

		var (relation, missingField, keyOnlyQualifiers, acceptedOnlyQualifiers) = ClassifyRelation(
			line, keyDesc, acceptedDesc, keyTier, acceptedTier,
			keyState, acceptedState, parsedNameTokens, keyHeadPhrase);

		var site = SiteOf(atom);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key's food-name head phrase: the description's normalized tokens up to the first token that
	/// production itself treats as state or preparation (<see cref="FdcLexicon.ModifierWords"/>, or
	/// <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// of that single token). This is the multi-word head the brief's relation 3 asks about —
	/// <c>"Bread, crumbs, dry, grated, plain"</c> → <c>bread crumbs</c>, because <c>dry</c> is the first
	/// production state token — while <c>"Tomatoes, crushed, canned"</c> stays single-word
	/// (<c>crushed</c> is a production modifier). The single-token
	/// <see cref="FdcDescriptionParser.Parse"/> <c>HeadTerm</c> cannot express the former.
	/// </summary>
	/// <param name="normalizedKeyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens, lower-cased and singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> normalizedKeyTokens)
	{
		ArgumentNullException.ThrowIfNull(normalizedKeyTokens);

		var phrase = new List<string>(normalizedKeyTokens.Count);
		foreach (var token in normalizedKeyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>Folds free text to production tokens: <see cref="FdcNormalizer.NormalizeToTokens"/> then <see cref="IngredientLineResolver.SingularizeToken"/> per token.</summary>
	/// <param name="text">The text to fold; null folds to empty.</param>
	/// <returns>The singular token list.</returns>
	public IReadOnlyList<string> SingularTokens(string? text) =>
		SingularTokens(_normalizer.NormalizeToTokens(text));

	/// <summary>
	/// Production's override lookup folds the raw text with <c>FdcMatcher.StripFromParenthesis</c>
	/// (private): content from the first <c>(</c> onward, lower-cased, trimmed. That one-step fold is
	/// applied here against the shipped <c>exact-overrides.json</c> keys (brief §4; named in the report).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		return (cut >= 0 ? rawText[..cut] : rawText).Trim().ToLowerInvariant();
	}

	private (string Relation, string? MissingField, IReadOnlyList<string>? KeyOnly, IReadOnlyList<string>? AcceptedOnly) ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return (RelationNoLabel, "expectedDescriptions", null, null);
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return (RelationPackUnitState, null, null, null);
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], keyHeadPhrase[0], StringComparison.OrdinalIgnoreCase))
		{
			return (RelationCompoundHeadLost, null, null, null);
		}

		var headKey = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm;
		var headAccepted = string.IsNullOrWhiteSpace(acceptedDesc)
			? string.Empty
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm;
		if (!HeadsAgree(headKey, headAccepted))
		{
			return (RelationSiblingFood, null, null, null);
		}

		if (keyState != acceptedState)
		{
			return (RelationStateMismatch, null, null, null);
		}

		if (string.IsNullOrEmpty(acceptedTier) || string.IsNullOrEmpty(keyTier))
		{
			return (RelationOther, string.IsNullOrEmpty(acceptedTier) ? "actualDataTypes" : "expectedDataTypes", null, null);
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return (RelationRowChoiceTier, null, null, null);
		}

		var keyQualifiers = QualifierSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedQualifiers = QualifierSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
		return (RelationSameHeadOtherQualifier, null, keyQualifiers.Except(acceptedQualifiers).ToArray(), acceptedQualifiers.Except(keyQualifiers).ToArray());
	}

	private static TraceAtom ChooseAtom(TraceLine line)
	{
		if (line.Atoms.Count == 0)
		{
			throw new InvalidOperationException($"Trace line {line.HoldoutId}#{line.LineIndex} has no atoms; cannot determine the decision site.");
		}

		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms[0];
	}

	private static string SiteOf(TraceAtom atom) => atom.Path.ToLowerInvariant() switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => atom.Reused ? SiteReuse : SiteRanker,
		_ => string.Empty,
	};

	private bool HeadsAgree(string headKey, string headAccepted)
	{
		var keyTokens = SingularTokens(_normalizer.NormalizeToTokens(headKey));
		var acceptedTokens = SingularTokens(_normalizer.NormalizeToTokens(headAccepted));
		return keyTokens.SequenceEqual(acceptedTokens, StringComparer.OrdinalIgnoreCase);
	}

	private static HashSet<string> QualifierSet(IReadOnlyList<string> qualifiers) =>
		new(qualifiers.Select(t => IngredientLineResolver.SingularizeToken(t.ToLowerInvariant())), StringComparer.OrdinalIgnoreCase);

	private FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private bool CarriesStateToken(string token)
	{
		_singleToken[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static IReadOnlyList<string> SingularTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));
}
