{"content":"namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one census or pairs invocation; owns the exit code.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the configured subcommand.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed invocation.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}
