{"content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Parsing;

using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads a HoldoutGate trace, classifies every auto-wrong line
/// (<c>auto == true &amp;&amp; correct == false</c>) through <see cref="AutoWrongClassifier"/>,
/// writes the TSV to <c>stdout</c> and the relation × site summary to <c>stderr</c>.
/// Refuses any trace whose record <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	System.IO.TextWriter output,
	System.IO.TextWriter error,
	ILogger<AutoWrongCensusRunner> logger) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly HashSet<string> AllowedSets = new(StringComparer.Ordinal) { "debug", "batch" };

	private readonly AutoWrongCensusOptions _options = options.Value;
	private readonly AutoWrongClassifier _classifier = classifier;
	private readonly System.IO.TextWriter _output = output;
	private readonly System.IO.TextWriter _error = error;
	private readonly ILogger<AutoWrongCensusRunner> _logger = logger;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		cancellationToken.ThrowIfCancellationRequested();

		if (string.IsNullOrEmpty(_options.Command))
		{
			AutoWrongCensusUsage.Print();
			return 1;
		}

		if (!System.IO.File.Exists(_options.TracePath))
		{
			_error.WriteLine($"error: trace file not found at '{_options.TracePath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set));
		if (refused is not null)
		{
			_error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch traces are classified (D-029).");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(lines);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();

		_output.WriteLine(string.Join('\t', TsvColumns));

		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;
		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = _classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				_error.WriteLine($"error: {ex.Message}");
				return 1;
			}

			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				_error.WriteLine($"error: {line.HoldoutId}#{line.LineIndex} has unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "<none>"}'; cannot determine the site.");
				continue;
			}

			results.Add(result);
			_output.WriteLine(string.Join('\t', TsvColumns.Select(c => Cell(result, c))));
		}

		WriteCensusSummary(lines, autoWrong, results, unknownSite);
		return unknownSite == 0 ? 0 : 1;
	}

	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		if (!System.IO.File.Exists(_options.CensusTsvPath))
		{
			_error.WriteLine($"error: census TSV not found at '{_options.CensusTsvPath}'.");
			return 1;
		}

		var censusRows = ReadCensusTsv(_options.CensusTsvPath);
		if (censusRows is null)
		{
			return 1;
		}

		var windowCompound = censusRows
			.Where(r => r.Blocker == "window" && (r.Route == "compound" || r.Route == "other"))
			.ToList();

		var traceIndex = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));

		_output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var missing = 0;
		foreach (var row in windowCompound)
		{
			if (!traceIndex.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missing++;
				continue;
			}

			var parsedNameHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(line.Atoms.FirstOrDefault()?.ParsedName ?? string.Empty)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(First(line.ExpectedDescriptions))));
			_output.WriteLine(string.Join('\t', Sanitize(row.HoldoutId), row.LineIndex.ToString(CultureInfo.InvariantCulture), Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			emitted++;
		}

		_error.WriteLine($"pairs: {emitted} of {windowCompound.Count} window compound/other rows emitted; {missing} not found in the trace.");
		return 0;
	}

	private IReadOnlyList<TraceLine>? ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		foreach (var raw in System.IO.File.ReadLines(path))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException($"Trace line in '{path}' deserialized to null."));
			}
			catch (JsonException ex)
			{
				_error.WriteLine($"error: unparseable trace line in '{path}': {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private sealed record CensusRow(string HoldoutId, int LineIndex, string Blocker, string Route);

	private IReadOnlyList<CensusRow>? ReadCensusTsv(string path)
	{
		var rows = new List<CensusRow>();
		var header = System.IO.File.ReadLines(path).FirstOrDefault()?.Split('\t');
		if (header is null)
		{
			_error.WriteLine($"error: census TSV '{path}' is empty.");
			return null;
		}

		int IndexOf(string name)
		{
			for (var i = 0; i < header.Length; i++)
			{
				if (header[i] == name)
				{
					return i;
				}
			}

			_error.WriteLine($"error: census TSV '{path}' has no '{name}' column.");
			return -1;
		}

		var holdoutId = IndexOf("holdoutId");
		var lineIndex = IndexOf("lineIndex");
		var blocker = IndexOf("blocker");
		var route = IndexOf("route");
		if (holdoutId < 0 || lineIndex < 0 || blocker < 0 || route < 0)
		{
			return null;
		}

		using var reader = new System.IO.StreamReader(path);
		reader.ReadLine(); // header
		string? raw;
		while ((raw = reader.ReadLine()) is not null)
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			var cells = raw.Split('\t');
			if (cells.Length <= Math.Max(holdoutId, Math.Max(lineIndex, Math.Max(blocker, route))) || !int.TryParse(cells[lineIndex], NumberStyles.Integer, CultureInfo.InvariantCulture, out var idx))
			{
				_error.WriteLine($"error: malformed census TSV row in '{path}': {raw}");
				return null;
			}

			rows.Add(new CensusRow(cells[holdoutId], idx, cells[blocker], cells[route]));
		}

		return rows;
	}

	private void WriteCensusSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<TraceLine> autoWrong, IReadOnlyList<ClassificationResult> results, int unknownSite)
	{
		var set = lines.FirstOrDefault()?.Set ?? string.Empty;
		_error.WriteLine($"autoWrongCensus set={set} lines={lines.Count} autoWrong={autoWrong.Count} classified={results.Count} unknownSite={unknownSite}");
		_error.WriteLine("relation\tsite\tcount");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation, StringComparer.Ordinal).ThenBy(g => g.Key.Site, StringComparer.Ordinal))
		{
			_error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_error.WriteLine($"other rate: {other}/{results.Count} ({(results.Count == 0 ? 0.0 : other * 100.0 / results.Count):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key, StringComparer.Ordinal);
		_error.WriteLine(missing.Any()
			? "missing fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}"))
			: "missing fields: none");

		var overrideSite = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		_error.WriteLine($"override-site lines: {overrideSite.Count}, exact-overrides.json key hits: {overrideSite.Count(r => r.OverrideKey == "yes")}");

		var reuseSite = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseFalse = 0;
		foreach (var r in reuseSite)
		{
			if (r.ParsedName.Length > 0 && !string.IsNullOrEmpty(r.RawText))
			{
				// The resolver's own exact-phrase rule, applied to the line's name vs the master it
				// linked: counts how many reuse-site auto-wrong lines the production ShouldReuse
				// would NOT have allowed by name (i.e. the reuse came through the fdcId link).
				var linked = r.RawText; // placeholder replaced below
				_ = linked;
			}
		}

		_ = reuseFalse;
		_error.WriteLine($"reuse-site lines: {reuseSite.Count}");

		var tier = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tier.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		_error.WriteLine($"row-choice-tier: {tier.Count} lines, key tier higher={keyHigher}, accepted tier higher={tier.Count - keyHigher}");

		var qualifierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		_error.WriteLine($"same-head-other-qualifier lines: {qualifierLines.Count}");
		foreach (var r in qualifierLines)
		{
			_error.WriteLine($"  {r.HoldoutId}#{r.LineIndex} key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static readonly string[] TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
		"acceptedTier", "keyTier", "acceptedState", "keyState",
		"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	private static string Cell(ClassificationResult r, string column) => column switch
	{
		"holdoutId" => r.HoldoutId,
		"lineIndex" => r.LineIndex.ToString(CultureInfo.InvariantCulture),
		"set" => r.Set,
		"relation" => r.Relation,
		"site" => r.Site,
		"overrideKey" => r.OverrideKey,
		"acceptedTier" => r.AcceptedTier,
		"keyTier" => r.KeyTier,
		"acceptedState" => r.AcceptedState,
		"keyState" => r.KeyState,
		"parsedName" => r.ParsedName,
		"keyHead" => r.KeyHead,
		"acceptedDesc" => r.AcceptedDesc,
		"keyDesc" => r.KeyDesc,
		"rawText" => r.RawText,
		_ => string.Empty,
	};

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private IReadOnlyList<string> _normalizerTokens(string text) => _classifier.KeyHeadPhrase([]); // placeholder, replaced
}
